\begin{prop}\ollabel{prop:bijection-inverse}
If $f\colon A \to B$ is !!{bijective}, there is a
function~$f^{-1}\colon B \to A$ so that for all $x \in A$,
$f^{-1}(f(x)) = x$ and for all $y \in B$, $f(f^{-1}(y)) = y$.
\end{prop}

